package com.bloodlink.service;
import com.bloodlink.model.Donor; import com.bloodlink.repository.DonorRepository; import java.util.*;
public final class DonorService { private final DonorRepository repo; public DonorService(DonorRepository repo){this.repo=repo;} public List<Donor> all(){return repo.findAll();} public List<Donor> search(String q){return repo.search(q);} public Donor save(Donor d){if(d.getName().isBlank())throw new IllegalArgumentException("Donor name is required.");if(d.getAge()<18||d.getAge()>65)throw new IllegalArgumentException("Donor age must be between 18 and 65.");if(d.getEmail().isBlank()||!d.getEmail().contains("@"))throw new IllegalArgumentException("Enter a valid email.");return repo.save(d);} public void delete(int id){repo.delete(id);} public long availableCount(){return all().stream().filter(Donor::isAvailable).count();}}
